-- Колия: блок «Как купить билеты» без опций. Шаг 1 из 2 (только добавляет, ничего не удаляет).
--   * route_pages.buy      блоки покупки страницы: {note, blocks: [{direct, h, steps, btns}]}, тексты на ru/uk/en/pl; нет перевода — нет ключа языка
--   * buy_templates        шаблоны блоков и примечаний для выпадающего списка в админке (kind: block | note)
--   * 80 страниц получают свои блоки, собранные из текущего сайта (тексты те же, что показываются сейчас, станции уже подставлены)
--   * 22 страницы «с пересадкой»: заголовок и подзаголовок раньше собирались автоматически из блоков, теперь записываются в texts
--   * kyiv_berlin, berlin_kyiv: splitx превращается в split (список станций)
-- Выполнить в Supabase → SQL Editor ДО слияния изменений. Старый сайт продолжает работать, повторный запуск безопасен.
-- Шаг 2 (db/buy-blocks-2-cleanup.sql) — после того, как новый код выложен и сайт пересобран.
begin;

alter table public.route_pages add column if not exists buy jsonb;

create table if not exists public.buy_templates (
    id bigint generated by default as identity primary key,
    kind text not null check (kind in ('block', 'note')),
    name text not null,
    data jsonb not null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique (kind, name)
);
alter table public.buy_templates enable row level security;
drop policy if exists buy_templates_read on public.buy_templates;
drop policy if exists buy_templates_write on public.buy_templates;
create policy buy_templates_read on public.buy_templates for select using (true);
create policy buy_templates_write on public.buy_templates for all to authenticated using (true) with check (true);
grant select on public.buy_templates to anon;
grant all on public.buy_templates to authenticated;

-- блоки покупки страниц (только там, где buy ещё пусто)
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Киев → Варшава и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Билеты на прямой поезд пользуются высоким спросом, поэтому рекомендуем покупать их сразу после начала продаж.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Київ → Варшава Центральна і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. На прямий поїзд квитки користуються великим попитом, тому радимо купувати їх одразу після початку продажу.","en":"Open the Ukrzaliznytsia app, choose the route Kyiv → Warszawa Centralna and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Tickets for the direct train are in high demand, so we recommend buying them as soon as sales open.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Kijów → Warszawa Centralna i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Bilety na pociąg bezpośredni cieszą się dużym popytem, dlatego warto kupić je zaraz po otwarciu sprzedaży."},{"ru":"Выберите место в купейном вагоне стандарта RIC и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце в купейному вагоні стандарту RIC і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a berth in an RIC-standard compartment car and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce w wagonie z przedziałami standardu RIC i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Киев → Варшава","uk":"Купити в застосунку УЗ квиток Київ → Варшава Центральна","en":"Buy the Kyiv → Warszawa Centralna ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Kijów → Warszawa Centralna"}}]},{"direct":false,"h":{"ru":"С пересадкой в Хелме","uk":"З пересадкою у Хелмі","en":"With a transfer in Chełm","pl":"Z przesiadką w Chełmie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Киев → Хелм и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Київ → Хелм і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kyiv → Chełm and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Kijów → Chełm i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Билет на поезд Хелм → Варшава приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Хелм → Варшава придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Chełm → Warszawa ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Chełm → Warszawa kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Киев → Хелм","uk":"Купити в застосунку УЗ квиток Київ → Хелм","en":"Buy the Kyiv → Chełm ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Kijów → Chełm"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Хелм → Варшава","uk":"Купити на сайті PKP Intercity квиток Хелм → Варшава","en":"Buy the Chełm → Warszawa ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Chełm → Warszawa"}}]}]}$j$::jsonb where id = 'kw' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Варшава → Киев и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Варшава Центральна → Київ і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Warszawa Centralna → Kyiv and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Warszawa Centralna → Kijów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место в купейном вагоне стандарта RIC и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце в купейному вагоні стандарту RIC і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a berth in an RIC-standard compartment car and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce w wagonie z przedziałami standardu RIC i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Варшава → Киев","uk":"Купити в застосунку УЗ квиток Варшава Центральна → Київ","en":"Buy the Warszawa Centralna → Kyiv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Warszawa Centralna → Kijów"}}]},{"direct":false,"h":{"ru":"С пересадкой в Хелме","uk":"З пересадкою у Хелмі","en":"With a transfer in Chełm","pl":"Z przesiadką w Chełmie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Хелм → Киев и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Хелм → Київ і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Chełm → Kyiv and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Chełm → Kijów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Билет на поезд Варшава → Хелм приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Варшава → Хелм придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Warszawa → Chełm ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Warszawa → Chełm kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Хелм → Киев","uk":"Купити в застосунку УЗ квиток Хелм → Київ","en":"Buy the Chełm → Kyiv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Chełm → Kijów"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Варшава → Хелм","uk":"Купити на сайті PKP Intercity квиток Варшава → Хелм","en":"Buy the Warszawa → Chełm ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Warszawa → Chełm"}}]}]}$j$::jsonb where id = 'wk' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Перемышле","uk":"З пересадкою у Перемишлі","en":"With a transfer in Przemyśl Główny","pl":"Z przesiadką w Przemyślu"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Киев → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Київ → Перемишль і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kyiv → Przemyśl and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Kijów → Przemyśl i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Билет на поезд Перемышль → Краков приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Перемишль → Краків придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Przemyśl → Kraków ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Przemyśl → Kraków kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Киев → Перемышль","uk":"Купити в застосунку УЗ квиток Київ → Перемишль","en":"Buy the Kyiv → Przemyśl ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Kijów → Przemyśl"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Перемышль → Краков","uk":"Купити на сайті PKP Intercity квиток Перемишль → Краків","en":"Buy the Przemyśl → Kraków ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Przemyśl → Kraków"}}]}]}$j$::jsonb where id = 'kyiv_krakow' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Перемышле","uk":"З пересадкою у Перемишлі","en":"With a transfer in Przemyśl Główny","pl":"Z przesiadką w Przemyślu"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Перемышль → Киев и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Перемишль → Київ і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Przemyśl → Kyiv and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Przemyśl → Kijów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Билет на поезд Краков → Перемышль приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Краків → Перемишль придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Kraków → Przemyśl ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Kraków → Przemyśl kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Перемышль → Киев","uk":"Купити в застосунку УЗ квиток Перемишль → Київ","en":"Buy the Przemyśl → Kyiv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Przemyśl → Kijów"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Краков → Перемышль","uk":"Купити на сайті PKP Intercity квиток Краків → Перемишль","en":"Buy the Kraków → Przemyśl ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Kraków → Przemyśl"}}]}]}$j$::jsonb where id = 'krakow_kyiv' and buy is null;
