update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Хелме","uk":"З пересадкою у Хелмі","en":"With a transfer in Chełm","pl":"Z przesiadką w Chełmie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Хелм и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Хелм і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Chełm and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose the train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Chełm i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz pociąg i opłać bilet."},{"ru":"Билет на поезд Хелм → Варшава приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Хелм → Варшава придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Chełm → Warszawa ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Chełm → Warszawa kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Хелм","uk":"Купити в застосунку УЗ квиток Дніпро → Хелм","en":"Buy the Dnipro → Chełm ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Chełm"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Хелм → Варшава","uk":"Купити на сайті PKP Intercity квиток Хелм → Варшава","en":"Buy the Chełm → Warszawa ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Chełm → Warszawa"}}]}]}$j$::jsonb where id = 'dnipro_warsaw' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Хелме","uk":"З пересадкою у Хелмі","en":"With a transfer in Chełm","pl":"Z przesiadką w Chełmie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Хелм → Днепр и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Хелм → Дніпро і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Chełm → Dnipro and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose the train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Chełm → Dnipro i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz pociąg i opłać bilet."},{"ru":"Билет на поезд Варшава → Хелм приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Варшава → Хелм придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Warszawa → Chełm ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Warszawa → Chełm kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Хелм → Днепр","uk":"Купити в застосунку УЗ квиток Хелм → Дніпро","en":"Buy the Chełm → Dnipro ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Chełm → Dnipro"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Варшава → Хелм","uk":"Купити на сайті PKP Intercity квиток Варшава → Хелм","en":"Buy the Warszawa → Chełm ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Warszawa → Chełm"}}]}]}$j$::jsonb where id = 'warsaw_dnipro' and buy is null;
