update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Хелм и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро-Головний → Хелм і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro-Holovnyi → Chełm and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro Główny → Chełm i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Хелм","uk":"Купити в застосунку УЗ квиток Дніпро-Головний → Хелм","en":"Buy the Dnipro-Holovnyi → Chełm ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro Główny → Chełm"}}]}]}$j$::jsonb where id = 'dnipro_khelm' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Хелм → Днепр и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Хелм → Дніпро-Головний і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Chełm → Dnipro-Holovnyi and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Chełm → Dnipro Główny i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Хелм → Днепр","uk":"Купити в застосунку УЗ квиток Хелм → Дніпро-Головний","en":"Buy the Chełm → Dnipro-Holovnyi ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Chełm → Dnipro Główny"}}]}]}$j$::jsonb where id = 'khelm_dnipro' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро-Головний → Перемишль-Головний і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro-Holovnyi → Przemyśl Główny and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro Główny → Przemyśl Główny i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Перемышль","uk":"Купити в застосунку УЗ квиток Дніпро-Головний → Перемишль-Головний","en":"Buy the Dnipro-Holovnyi → Przemyśl Główny ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro Główny → Przemyśl Główny"}}]}]}$j$::jsonb where id = 'dnipro_przemysl' and buy is null;
