update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Одесса → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Одеса → Перемишль-Головний і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Odesa → Przemyśl Główny and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Odessa → Przemyśl Główny i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Одесса → Перемышль","uk":"Купити в застосунку УЗ квиток Одеса → Перемишль-Головний","en":"Buy the Odesa → Przemyśl Główny ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Odessa → Przemyśl Główny"}}]}]}$j$::jsonb where id = 'odesa_przemysl' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Перемышль → Одесса и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Перемишль-Головний → Одеса і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Przemyśl Główny → Odesa and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Przemyśl Główny → Odessa i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Перемышль → Одесса","uk":"Купити в застосунку УЗ квиток Перемишль-Головний → Одеса","en":"Buy the Przemyśl Główny → Odesa ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Przemyśl Główny → Odessa"}}]}]}$j$::jsonb where id = 'przemysl_odesa' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Раве-Русской","uk":"З пересадкою у Раві-Руській","en":"With a transfer in Rava-Ruska","pl":"Z przesiadką w Rawie Ruskiej"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Львов → Варшава и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Львів → Варшава Центральна і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Lviv → Warszawa Centralna and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Lwów → Warszawa Centralna i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Нажмите «З пересадками» и в предложенном варианте по очереди выберите места для каждого поезда, затем оплатите оба билета в приложении.","uk":"Натисніть «З пересадками» і в запропонованому варіанті по черзі оберіть місця для кожного поїзда, а потім сплатіть обидва квитки в застосунку.","en":"Tap “З пересадками” (With transfers), then in the option offered pick seats for each train in turn and pay for both tickets in the app.","pl":"Naciśnij „З пересадками” (z przesiadkami), a w zaproponowanym wariancie po kolei wybierz miejsca w każdym pociągu i opłać oba bilety w aplikacji."},{"ru":"После покупки сохраните электронные билеты в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save the e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билеты Львов → Варшава","uk":"Купити в застосунку УЗ квитки Львів → Варшава Центральна","en":"Buy the Lviv → Warszawa Centralna tickets in the UZ app","pl":"Kup w aplikacji UZ bilety Lwów → Warszawa Centralna"}}]}]}$j$::jsonb where id = 'lviv_warsaw' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Раве-Русской","uk":"З пересадкою у Раві-Руській","en":"With a transfer in Rava-Ruska","pl":"Z przesiadką w Rawie Ruskiej"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Варшава → Львов и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Варшава Центральна → Львів і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Warszawa Centralna → Lviv and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Warszawa Centralna → Lwów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Нажмите «З пересадками» и в предложенном варианте по очереди выберите места для каждого поезда, затем оплатите оба билета в приложении.","uk":"Натисніть «З пересадками» і в запропонованому варіанті по черзі оберіть місця для кожного поїзда, а потім сплатіть обидва квитки в застосунку.","en":"Tap “З пересадками” (With transfers), then in the option offered pick seats for each train in turn and pay for both tickets in the app.","pl":"Naciśnij „З пересадками” (z przesiadkami), a w zaproponowanym wariancie po kolei wybierz miejsca w każdym pociągu i opłać oba bilety w aplikacji."},{"ru":"После покупки сохраните электронные билеты в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save the e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билеты Варшава → Львов","uk":"Купити в застосунку УЗ квитки Варшава Центральна → Львів","en":"Buy the Warszawa Centralna → Lviv tickets in the UZ app","pl":"Kup w aplikacji UZ bilety Warszawa Centralna → Lwów"}}]}]}$j$::jsonb where id = 'warsaw_lviv' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Перемышле","uk":"З пересадкою у Перемишлі","en":"With a transfer in Przemyśl Główny","pl":"Z przesiadką w Przemyślu"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Львов → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Львів → Перемишль і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Lviv → Przemyśl and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Lwów → Przemyśl i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Билет на поезд Перемышль → Краков приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Перемишль → Краків придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Przemyśl → Kraków ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Przemyśl → Kraków kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Львов → Перемышль","uk":"Купити в застосунку УЗ квиток Львів → Перемишль","en":"Buy the Lviv → Przemyśl ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Lwów → Przemyśl"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Перемышль → Краков","uk":"Купити на сайті PKP Intercity квиток Перемишль → Краків","en":"Buy the Przemyśl → Kraków ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Przemyśl → Kraków"}}]}]}$j$::jsonb where id = 'lviv_krakow' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Перемышле","uk":"З пересадкою у Перемишлі","en":"With a transfer in Przemyśl Główny","pl":"Z przesiadką w Przemyślu"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Перемышль → Львов и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Перемишль → Львів і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Przemyśl → Lviv and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Przemyśl → Lwów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Билет на поезд Краков → Перемышль приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд Краків → Перемишль придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the Kraków → Przemyśl ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg Kraków → Przemyśl kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Перемышль → Львов","uk":"Купити в застосунку УЗ квиток Перемишль → Львів","en":"Buy the Przemyśl → Lviv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Przemyśl → Lwów"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Краков → Перемышль","uk":"Купити на сайті PKP Intercity квиток Краків → Перемишль","en":"Buy the Kraków → Przemyśl ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Kraków → Przemyśl"}}]}]}$j$::jsonb where id = 'krakow_lviv' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Львов → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Львів → Перемишль-Головний і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Lviv → Przemyśl Główny and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Lwów → Przemyśl Główny i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите подходящий поезд и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть відповідний поїзд і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Choose a suitable train and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz odpowiedni pociąg i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Львов → Перемышль","uk":"Купити в застосунку УЗ квиток Львів → Перемишль-Головний","en":"Buy the Lviv → Przemyśl Główny ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Lwów → Przemyśl Główny"}}]}]}$j$::jsonb where id = 'lviv_przemysl' and buy is null;
