update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"blocks":[{"direct":true,"h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Кременчуг → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Кременчук → Перемишль-Головний і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route Kremenchuk → Przemyśl Główny and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Krzemieńczuk → Przemyśl Główny i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."}],"btns":[{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Кременчуг → Перемышль","uk":"Купити в застосунку УЗ квиток Кременчук → Перемишль-Головний","en":"Buy the Kremenchuk → Przemyśl Główny ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Krzemieńczuk → Przemyśl Główny"}}]}]}$j$::jsonb where id = 'kremenchuk_przemysl' and buy is null;
