update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Мукачево","uk":"З пересадкою у Мукачеві","en":"With a transfer in Mukachevo","pl":"Z przesiadką w Mukaczewie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Мукачево → Кременчуг и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Мукачево → Кременчук і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Mukachevo → Kremenchuk and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Mukaczewo → Krzemieńczuk i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},{"ru":"Купите билет на поезд Будапешт → Мукачево в приложении «Укрзалізниця». Также билет можно приобрести заранее у венгерского перевозчика MÁV — на официальном сайте jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Придбайте квиток на поїзд Будапешт → Мукачево у застосунку «Укрзалізниця». Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на офіційному сайті jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"Buy the Budapest → Mukachevo ticket in the Ukrzaliznytsia app. You can also buy the ticket in advance from the Hungarian carrier MÁV, on the official site jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Kup bilet na pociąg Budapest → Mukaczewo w aplikacji Ukrzaliznytsia. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na oficjalnej stronie jegy.mav.hu lub w aplikacji MÁVPlusz. Zazwyczaj bilety MÁV są tańsze."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Мукачево → Кременчуг","uk":"Купити в застосунку УЗ квиток Мукачево → Кременчук","en":"Buy the Mukachevo → Kremenchuk ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Mukaczewo → Krzemieńczuk"}},{"pri":false,"url":"https://www.intercity.pl/","t":{"ru":"Купить на сайте PKP Intercity билет Будапешт → Мукачево","uk":"Купити на сайті PKP Intercity квиток Будапешт → Мукачево","en":"Buy the Budapest → Mukachevo ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet Budapest → Mukaczewo"}}]}]}$j$::jsonb where id = 'budapest_kremenchuk' and buy is null;
