update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Чопе","uk":"З пересадкою у Чопі","en":"With a transfer in Chop","pl":"Z przesiadką w Czopie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Чоп и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 003П и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Чоп і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 003П і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Chop and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 003П and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Czop i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 003П i opłać bilet."},{"ru":"Поезд Чоп → Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день. Также билет можно приобрести заранее у венгерского перевозчика MÁV — на jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Поїзд Чоп → Будапешт відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня. Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"The train Chop → Budapest departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day. You can also buy a ticket in advance from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Pociąg Czop → Budapest odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na jegy.mav.hu lub w aplikacji MÁVPlusz. Zwykle bilety MÁV są tańsze."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Чоп","uk":"Купити в застосунку УЗ квиток Дніпро → Чоп","en":"Buy the Dnipro → Chop ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Czop"}},{"pri":false,"url":"https://jegy.mav.hu/","t":{"ru":"Купить на сайте MÁV билет Чоп → Будапешт","uk":"Купити на сайті MÁV квиток Чоп → Будапешт","en":"Buy the Chop → Budapest ticket on MÁV","pl":"Kup na stronie MÁV bilet Czop → Budapest"}}]},{"direct":false,"h":{"ru":"С пересадкой в Мукачево","uk":"З пересадкою у Мукачеві","en":"With a transfer in Mukachevo","pl":"Z przesiadką w Mukaczewie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Мукачево и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 003П и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Мукачево і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 003П і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Mukachevo and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 003П and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Mukaczewo i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 003П i opłać bilet."},{"ru":"Поезд из Мукачево в Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день.","uk":"Поїзд із Мукачева до Будапешта відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня.","en":"The train from Mukachevo to Budapest Keleti departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day.","pl":"Pociąg z Mukaczewo do Budapest Keleti odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Мукачево","uk":"Купити в застосунку УЗ квиток Дніпро → Мукачево","en":"Buy the Dnipro → Mukachevo ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Mukaczewo"}},{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Мукачево → Будапешт","uk":"Купити в застосунку УЗ квиток Мукачево → Будапешт","en":"Buy the Mukachevo → Budapest ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Mukaczewo → Budapest"}}]},{"direct":false,"h":{"ru":"С пересадкой в Киеве","uk":"З пересадкою у Києві","en":"With a transfer in Kyiv","pl":"Z przesiadką w Kijowie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Киев и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 119П и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Київ і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 119П і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Kyiv and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 119П and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Kijów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 119П i opłać bilet."},{"ru":"Поезд из Киева в Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день.","uk":"Поїзд із Києва до Будапешта відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня.","en":"The train from Kyiv to Budapest Keleti departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day.","pl":"Pociąg z Kijowa do Budapest Keleti odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Киев","uk":"Купити в застосунку УЗ квиток Дніпро → Київ","en":"Buy the Dnipro → Kyiv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Kijów"}},{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Киев → Будапешт","uk":"Купити в застосунку УЗ квиток Київ → Будапешт","en":"Buy the Kyiv → Budapest ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Kijów → Budapest"}}]}]}$j$::jsonb where id = 'dnipro_budapest' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Перемышле","uk":"З пересадкою у Перемишлі","en":"With a transfer in Przemyśl Główny","pl":"Z przesiadką w Przemyślu"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите поезд 073П и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Перемишль і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть поїзд 073П і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Przemyśl and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose train 073П and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Przemyśl i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 09:00 czasu kijowskiego. Wybierz pociąg 073П i opłać bilet."},{"ru":"Билет Перемышль → Прага на поезд RJ приобретите отдельно у чешского перевозчика RegioJet — на официальном сайте regiojet.cz или в приложении RegioJet.","uk":"Квиток Перемишль → Прага на поїзд RJ придбайте окремо в чеського перевізника RegioJet — на офіційному сайті regiojet.cz або в застосунку RegioJet.","en":"Buy the Przemyśl → Prague ticket for the RJ train separately from the Czech carrier RegioJet, on regiojet.cz or in the RegioJet app.","pl":"Bilet Przemyśl → Praga na pociąg RJ kup osobno u czeskiego przewoźnika RegioJet — na stronie regiojet.cz lub w aplikacji RegioJet."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Перемышль","uk":"Купити в застосунку УЗ квиток Дніпро → Перемишль","en":"Buy the Dnipro → Przemyśl ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Przemyśl"}},{"pri":false,"url":"https://regiojet.cz/","t":{"ru":"Купить на сайте RegioJet билет Перемышль → Прага","uk":"Купити на сайті RegioJet квиток Перемишль → Прага","en":"Buy the Przemyśl → Prague ticket on RegioJet","pl":"Kup bilet Przemyśl → Praga na stronie RegioJet"}}]},{"direct":false,"h":{"ru":"С пересадкой в Чопе","uk":"З пересадкою у Чопі","en":"With a transfer in Chop","pl":"Z przesiadką w Czopie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Чоп и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 003П и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Чоп і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 003П і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Chop and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 003П and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Czop i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 003П i opłać bilet."},{"ru":"Билет Чоп → Прага на поезд RJ приобретите отдельно у чешского перевозчика RegioJet — на официальном сайте regiojet.cz или в приложении RegioJet.","uk":"Квиток Чоп → Прага на поїзд RJ придбайте окремо в чеського перевізника RegioJet — на офіційному сайті regiojet.cz або в застосунку RegioJet.","en":"Buy the Chop → Prague ticket for the RJ train separately from the Czech carrier RegioJet, on regiojet.cz or in the RegioJet app.","pl":"Bilet Czop → Praga na pociąg RJ kup osobno u czeskiego przewoźnika RegioJet — na stronie regiojet.cz lub w aplikacji RegioJet."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Чоп","uk":"Купити в застосунку УЗ квиток Дніпро → Чоп","en":"Buy the Dnipro → Chop ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Czop"}},{"pri":false,"url":"https://regiojet.cz/","t":{"ru":"Купить на сайте RegioJet билет Чоп → Прага","uk":"Купити на сайті RegioJet квиток Чоп → Прага","en":"Buy the Chop → Prague ticket on RegioJet","pl":"Kup bilet Czop → Praga na stronie RegioJet"}}]}]}$j$::jsonb where id = 'dnipro_prague' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте ÖBB.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті ÖBB.","en":"Train schedules may change. Check the latest information in the UZ app and on the ÖBB website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie ÖBB."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Чопе","uk":"З пересадкою у Чопі","en":"With a transfer in Chop","pl":"Z przesiadką w Czopie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Днепр → Чоп и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 003П и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Дніпро → Чоп і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 003П і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Dnipro → Chop and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 003П and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Dnipro → Czop i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 003П i opłać bilet."},{"ru":"Поезд Чоп → Вена отправляется через сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается через два дня. Также билет можно приобрести заранее у австрийского перевозчика ÖBB — на tickets.oebb.at или в приложении ÖBB Tickets. Но в таком случае он будет существенно дороже, чем в приложении «Укрзалізниця».","uk":"Поїзд Чоп → Відень відправляється через добу, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається через два дні. Також квиток можна придбати заздалегідь в австрійського перевізника ÖBB — на tickets.oebb.at або в застосунку ÖBB Tickets. Але в такому разі він буде значно дорожчим, ніж у застосунку «Укрзалізниця».","en":"The train Chop → Vienna departs a day later, so ticket sales for it in the Ukrzaliznytsia app open in two days. You can also buy a ticket in advance from the Austrian carrier ÖBB, on tickets.oebb.at or in the ÖBB Tickets app. In that case, however, it will be considerably more expensive than in the Ukrzaliznytsia app.","pl":"Pociąg Czop → Wiedeń odjeżdża za dobę, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza za dwa dni. Bilet można też kupić wcześniej u austriackiego przewoźnika ÖBB — na tickets.oebb.at lub w aplikacji ÖBB Tickets. W takim przypadku będzie on jednak znacznie droższy niż w aplikacji Ukrzaliznytsia."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Днепр → Чоп","uk":"Купити в застосунку УЗ квиток Дніпро → Чоп","en":"Buy the Dnipro → Chop ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Dnipro → Czop"}},{"pri":false,"url":"https://tickets.oebb.at/","t":{"ru":"Купить на сайте ÖBB билет Чоп → Вена","uk":"Купити на сайті ÖBB квиток Чоп → Відень","en":"Buy the Chop → Vienna ticket on ÖBB","pl":"Kup na stronie ÖBB bilet Czop → Wiedeń"}}]}]}$j$::jsonb where id = 'dnipro_vienna' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Мукачево","uk":"З пересадкою у Мукачеві","en":"With a transfer in Mukachevo","pl":"Z przesiadką w Mukaczewie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Харьков → Мукачево и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 017О и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Харків → Мукачево і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 017О і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kharkiv → Mukachevo and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 017О and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Charków → Mukaczewo i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 017О i opłać bilet."},{"ru":"Поезд Мукачево → Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день. Также билет можно приобрести заранее у венгерского перевозчика MÁV — на jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Поїзд Мукачево → Будапешт відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня. Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"The train Mukachevo → Budapest departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day. You can also buy a ticket in advance from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Pociąg Mukaczewo → Budapest odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na jegy.mav.hu lub w aplikacji MÁVPlusz. Zwykle bilety MÁV są tańsze."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Харьков → Мукачево","uk":"Купити в застосунку УЗ квиток Харків → Мукачево","en":"Buy the Kharkiv → Mukachevo ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Charków → Mukaczewo"}},{"pri":false,"url":"https://jegy.mav.hu/","t":{"ru":"Купить на сайте MÁV билет Мукачево → Будапешт","uk":"Купити на сайті MÁV квиток Мукачево → Будапешт","en":"Buy the Mukachevo → Budapest ticket on MÁV","pl":"Kup na stronie MÁV bilet Mukaczewo → Budapest"}}]},{"direct":false,"h":{"ru":"С пересадкой в Киеве","uk":"З пересадкою у Києві","en":"With a transfer in Kyiv","pl":"Z przesiadką w Kijowie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Харьков → Киев и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 063О и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Харків → Київ і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 063О і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kharkiv → Kyiv and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 063О and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Charków → Kijów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 063О i opłać bilet."},{"ru":"Поезд из Киева в Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день.","uk":"Поїзд із Києва до Будапешта відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня.","en":"The train from Kyiv to Budapest Keleti departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day.","pl":"Pociąg z Kijowa do Budapest Keleti odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Харьков → Киев","uk":"Купити в застосунку УЗ квиток Харків → Київ","en":"Buy the Kharkiv → Kyiv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Charków → Kijów"}},{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Киев → Будапешт","uk":"Купити в застосунку УЗ квиток Київ → Будапешт","en":"Buy the Kyiv → Budapest ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Kijów → Budapest"}}]},{"direct":false,"h":{"ru":"С пересадкой во Львове","uk":"З пересадкою у Львові","en":"With a transfer in Lviv","pl":"Z przesiadką we Lwowie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Харьков → Львов и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 021О и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Харків → Львів і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 021О і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kharkiv → Lviv and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 021О and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Charków → Lwów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 021О i opłać bilet."},{"ru":"Поезд из Львов в Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день.","uk":"Поїзд із Львів до Будапешта відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня.","en":"The train from Lviv to Budapest Keleti departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day.","pl":"Pociąg z Lwów do Budapest Keleti odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Харьков → Львов","uk":"Купити в застосунку УЗ квиток Харків → Львів","en":"Buy the Kharkiv → Lviv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Charków → Lwów"}},{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Львов → Будапешт","uk":"Купити в застосунку УЗ квиток Львів → Будапешт","en":"Buy the Lviv → Budapest ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Lwów → Budapest"}}]}]}$j$::jsonb where id = 'kharkiv_budapest' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Чопе","uk":"З пересадкою у Чопі","en":"With a transfer in Chop","pl":"Z przesiadką w Czopie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Харьков → Ужгород и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 017О и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Харків → Ужгород і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 017О і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kharkiv → Uzhhorod and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 017О and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Charków → Użhorod i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 017О i opłać bilet."},{"ru":"Билет Чоп → Прага на поезд RJ приобретите отдельно у чешского перевозчика RegioJet — на официальном сайте regiojet.cz или в приложении RegioJet.","uk":"Квиток Чоп → Прага на поїзд RJ придбайте окремо в чеського перевізника RegioJet — на офіційному сайті regiojet.cz або в застосунку RegioJet.","en":"Buy the Chop → Prague ticket for the RJ train separately from the Czech carrier RegioJet, on regiojet.cz or in the RegioJet app.","pl":"Bilet Czop → Praga na pociąg RJ kup osobno u czeskiego przewoźnika RegioJet — na stronie regiojet.cz lub w aplikacji RegioJet."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Харьков → Ужгород","uk":"Купити в застосунку УЗ квиток Харків → Ужгород","en":"Buy the Kharkiv → Uzhhorod ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Charków → Użhorod"}},{"pri":false,"url":"https://regiojet.cz/","t":{"ru":"Купить на сайте RegioJet билет Чоп → Прага","uk":"Купити на сайті RegioJet квиток Чоп → Прага","en":"Buy the Chop → Prague ticket on RegioJet","pl":"Kup bilet Czop → Praga na stronie RegioJet"}}]},{"direct":false,"h":{"ru":"С пересадкой в Перемышле","uk":"З пересадкою у Перемишлі","en":"With a transfer in Przemyśl Główny","pl":"Z przesiadką w Przemyślu"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Харьков → Перемышль и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите поезд 063О и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Харків → Перемишль і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть поїзд 063О і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Kharkiv → Przemyśl and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose train 063О and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Charków → Przemyśl i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 09:00 czasu kijowskiego. Wybierz pociąg 063О i opłać bilet."},{"ru":"Билет Перемышль → Прага на поезд RJ приобретите отдельно у чешского перевозчика RegioJet — на официальном сайте regiojet.cz или в приложении RegioJet.","uk":"Квиток Перемишль → Прага на поїзд RJ придбайте окремо в чеського перевізника RegioJet — на офіційному сайті regiojet.cz або в застосунку RegioJet.","en":"Buy the Przemyśl → Prague ticket for the RJ train separately from the Czech carrier RegioJet, on regiojet.cz or in the RegioJet app.","pl":"Bilet Przemyśl → Praga na pociąg RJ kup osobno u czeskiego przewoźnika RegioJet — na stronie regiojet.cz lub w aplikacji RegioJet."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Харьков → Перемышль","uk":"Купити в застосунку УЗ квиток Харків → Перемишль","en":"Buy the Kharkiv → Przemyśl ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Charków → Przemyśl"}},{"pri":false,"url":"https://regiojet.cz/","t":{"ru":"Купить на сайте RegioJet билет Перемышль → Прага","uk":"Купити на сайті RegioJet квиток Перемишль → Прага","en":"Buy the Przemyśl → Prague ticket on RegioJet","pl":"Kup bilet Przemyśl → Praga na stronie RegioJet"}}]}]}$j$::jsonb where id = 'kharkiv_prague' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Мукачево","uk":"З пересадкою у Мукачеві","en":"With a transfer in Mukachevo","pl":"Z przesiadką w Mukaczewie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Одесса → Мукачево и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 038Ш и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Одеса → Мукачево і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 038Ш і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Odesa → Mukachevo and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 038Ш and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Odessa → Mukaczewo i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 038Ш i opłać bilet."},{"ru":"Поезд Мукачево → Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день. Также билет можно приобрести заранее у венгерского перевозчика MÁV — на jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Поїзд Мукачево → Будапешт відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня. Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"The train Mukachevo → Budapest departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day. You can also buy a ticket in advance from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Pociąg Mukaczewo → Budapest odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na jegy.mav.hu lub w aplikacji MÁVPlusz. Zwykle bilety MÁV są tańsze."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Одесса → Мукачево","uk":"Купити в застосунку УЗ квиток Одеса → Мукачево","en":"Buy the Odesa → Mukachevo ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Odessa → Mukaczewo"}},{"pri":false,"url":"https://jegy.mav.hu/","t":{"ru":"Купить на сайте MÁV билет Мукачево → Будапешт","uk":"Купити на сайті MÁV квиток Мукачево → Будапешт","en":"Buy the Mukachevo → Budapest ticket on MÁV","pl":"Kup na stronie MÁV bilet Mukaczewo → Budapest"}}]},{"direct":false,"h":{"ru":"С пересадкой во Львове","uk":"З пересадкою у Львові","en":"With a transfer in Lviv","pl":"Z przesiadką we Lwowie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Одесса → Львов и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 012Ш и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Одеса → Львів і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 012Ш і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Odesa → Lviv and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 012Ш and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Odessa → Lwów i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 012Ш i opłać bilet."},{"ru":"Поезд из Львов в Будапешт отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день.","uk":"Поїзд із Львів до Будапешта відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня.","en":"The train from Lviv to Budapest Keleti departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the next day.","pl":"Pociąg z Lwów do Budapest Keleti odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza następnego dnia."},{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."}],"btns":[{"pri":true,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Одесса → Львов","uk":"Купити в застосунку УЗ квиток Одеса → Львів","en":"Buy the Odesa → Lviv ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Odessa → Lwów"}},{"pri":false,"url":"https://app.uz.gov.ua/start","t":{"ru":"Купить в приложении УЗ билет Львов → Будапешт","uk":"Купити в застосунку УЗ квиток Львів → Будапешт","en":"Buy the Lviv → Budapest ticket in the UZ app","pl":"Kup w aplikacji UZ bilet Lwów → Budapest"}}]}]}$j$::jsonb where id = 'odesa_budapest' and buy is null;
update public.route_pages set buy = $j${"note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"blocks":[{"direct":false,"h":{"ru":"С пересадкой в Чопе","uk":"З пересадкою у Чопі","en":"With a transfer in Chop","pl":"Z przesiadką w Czopie"},"steps":[{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут Одесса → Ужгород и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 038Ш и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут Одеса → Ужгород і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 038Ш і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route Odesa → Uzhhorod and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 038Ш and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę Odessa → Użhorod i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 038Ш i opłać bilet."},{"ru":"Билет Чоп → Прага на поезд RJ приобретите отдельно у чешского перевозчика RegioJet — на официальном сайте regiojet.cz или в приложении RegioJet.","uk":"Квиток Чоп → Прага на поїзд RJ придбайте окремо в чеського перевізника RegioJet — на офіційному сайті regiojet.cz або в застосунку RegioJet.","en":"Buy the Chop → Prague ticket for the RJ train separately from the Czech carrier RegioJet, on regiojet.cz or in the RegioJet app.","pl":"Bilet Czop → Praga na pociąg RJ kup osobno u cz