-- тексты страниц «с пересадкой» (раньше собирались из списка блоков)
update public.route_pages set texts = $j${"ru":{"title":"Будапешт → Днепр поездом | Колія","desc":"Поезда Будапешт — Днепр с пересадкой в Киеве и Мукачево: время, станции, длительность.","h1":"Поездом: Будапешт → Днепр","lead":"Расписание поездов Будапешт — Днепр: варианты с пересадкой в Киеве и Мукачево. Время в пути, остановки и информация о покупке билетов."},"uk":{"title":"Будапешт → Дніпро потягом | Колія","desc":"Поїзди Будапешт — Дніпро з пересадкою у Києві та Мукачеві: час, станції, тривалість.","h1":"Потягом: Будапешт → Дніпро","lead":"Розклад поїздів Будапешт — Дніпро: варіанти з пересадкою у Києві та Мукачеві. Час у дорозі, зупинки та інформація про купівлю квитків."},"en":{"title":"Budapest → Dnipro by train | Koliya","desc":"Trains Budapest — Dnipro with a change in Kyiv and Mukachevo: times, stations, duration.","h1":"By train: Budapest → Dnipro","lead":"Train timetable Budapest — Dnipro: connections with a change in Kyiv and Mukachevo. Journey time, stops and ticket information."},"pl":{"title":"Budapest → Dnipro pociągiem | Koliya","desc":"Pociągi Budapest — Dnipro z przesiadką w Kijowie i Mukaczewie: godziny, stacje, czas podróży.","h1":"Pociągiem: Budapest → Dnipro","lead":"Rozkład pociągów Budapest — Dnipro: połączenia z przesiadką w Kijowie i Mukaczewie. Czas podróży, postoje i informacje o zakupie biletów."}}$j$::jsonb where id = 'budapest_dnipro' and (texts is null or texts::jsonb = '{}'::jsonb);
update public.route_pages set texts = $j${"ru":{"title":"Будапешт → Харьков поездом | Колія","desc":"Поезда Будапешт — Харьков с пересадкой в Киеве и Львове и Мукачево: время, станции, длительность.","h1":"Поездом: Будапешт → Харьков","lead":"Расписание поездов Будапешт — Харьков: варианты с пересадкой в Киеве и Львове и Мукачево. Время в пути, остановки и информация о покупке билетов."},"uk":{"title":"Будапешт → Харків потягом | Колія","desc":"Поїзди Будапешт — Харків з пересадкою у Києві та Львові та Мукачеві: час, станції, тривалість.","h1":"Потягом: Будапешт → Харків","lead":"Розклад поїздів Будапешт — Харків: варіанти з пересадкою у Києві та Львові та Мукачеві. Час у дорозі, зупинки та інформація про купівлю квитків."},"en":{"title":"Budapest → Kharkiv by train | Koliya","desc":"Trains Budapest — Kharkiv with a change in Kyiv and Lviv and Mukachevo: times, stations, duration.","h1":"By train: Budapest → Kharkiv","lead":"Train timetable Budapest — Kharkiv: connections with a change in Kyiv and Lviv and Mukachevo. Journey time, stops and ticket information."},"pl":{"title":"Budapest → Charków pociągiem | Koliya","desc":"Pociągi Budapest — Charków z przesiadką w Kijowie i Lwowie i Mukaczewie: godziny, stacje, czas podróży.","h1":"Pociągiem: Budapest → Charków","lead":"Rozkład pociągów Budapest — Charków: połączenia z przesiadką w Kijowie i Lwowie i Mukaczewie. Czas podróży, postoje i informacje o zakupie biletów."}}$j$::jsonb where id = 'budapest_kharkiv' and (texts is null or texts::jsonb = '{}'::jsonb);
