-- splitx -> split
update public.route_pages set extra = coalesce(extra::jsonb, '{}'::jsonb) || jsonb_build_object('split', $j$["Перемышль","Хелм"]$j$::jsonb) where id = 'kyiv_berlin';
update public.route_pages set extra = coalesce(extra::jsonb, '{}'::jsonb) || jsonb_build_object('split', $j$["Перемышль","Варшава","Хелм"]$j$::jsonb) where id = 'berlin_kyiv';

-- шаблоны: каждый существующий блок (название: «заголовок · откуда → куда», при повторе на странице добавляется номер) и примечания
insert into public.buy_templates (kind, name, data)
select 'block',
       (b.blk->'h'->>'ru') || ' · ' || r.from_name || ' → ' || r.to_name || case when b.n > 1 then ' (' || b.n || ')' else '' end,
       b.blk
from (select p.id, x.blk, row_number() over (partition by p.id, x.blk->'h'->>'ru' order by x.ord) as n
      from public.route_pages p, jsonb_array_elements(p.buy->'blocks') with ordinality as x(blk, ord)
      where p.buy is not null) b
join public.route_pages r on r.id = b.id
on conflict (kind, name) do nothing;
insert into public.buy_templates (kind, name, data) values ('note', $n$Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.$n$, $j${"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."}$j$::jsonb) on conflict (kind, name) do nothing;
