insert into public.buy_templates (kind, name, data) values ('note', $n$Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и в приложении ZSSK.$n$, $j${"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и в приложении ZSSK.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та в застосунку ZSSK.","en":"Train schedules may change. Check the latest information in the UZ app and in the ZSSK app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i w aplikacji ZSSK."}$j$::jsonb) on conflict (kind, name) do nothing;
