insert into public.buy_templates (kind, name, data) values ('note', $n$Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ, на сайте PKP Intercity и на сайте DB.$n$, $j${"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ, на сайте PKP Intercity и на сайте DB.","uk":"Графіки руху поїздів можуть змінитися, актуальну інформацію дивіться в застосунку УЗ, на сайті PKP Intercity та на сайті DB.","en":"Train schedules may change. Check the latest information in the UZ app, on the PKP Intercity website and on the DB website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ oraz na stronach PKP Intercity i DB."}$j$::jsonb) on conflict (kind, name) do nothing;
insert into public.buy_templates (kind, name, data) values ('note', $n$Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ, в приложении ČD My Train и на сайте RegioJet.$n$, $j${"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ, в приложении ČD My Train и на сайте RegioJet.","uk":"Графіки руху поїздів можуть змінитися, актуальну інформацію дивіться в застосунку УЗ, у застосунку ČD My Train та на сайті RegioJet.","en":"Train schedules may change. Check the latest information in the UZ app, in the ČD My Train app and on the RegioJet website.","pl":"Rozkłady jazdy mogą się zmienić, aktualne informacje sprawdź w aplikacji UZ, w aplikacji ČD My Train i na stronie RegioJet."}$j$::jsonb) on conflict (kind, name) do nothing;
insert into public.buy_templates (kind, name, data) values ('note', $n$Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте MÁV.$n$, $j${"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте MÁV.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті MÁV.","en":"Train schedules may change. Check the latest information in the UZ app and on the MÁV website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie MÁV."}$j$::jsonb) on conflict (kind, name) do nothing;

select (select count(*) from public.route_pages where buy is not null) as pages_with_buy,
       (select count(*) from public.buy_templates) as templates;
commit;
